import { Link } from "react-router-dom";
import "../nav/nav.css"
import { useDispatch } from "react-redux";
import { fetchProductsByCategory } from "../../features/products/productsSlice";


const DropdownTab = ({name, items}) => {
        const dispatch = useDispatch()

